import sys

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n = data[0]
    points = [(data[1 + 2 * i], data[2 + 2 * i]) for i in range(n)]

    full = (1 << n) - 1
    retained = []
    for k, (xk, yk) in enumerate(points):
        bit = 1 << k
        comparable = bit
        for i, (x, y) in enumerate(points):
            if (x < xk and y < yk) or (x > xk and y > yk):
                comparable |= 1 << i
        # Keep the selected ball and all balls incomparable with it.
        retained.append(full ^ (comparable ^ bit))

    seen = {full}
    stack = [full]
    while stack:
        state = stack.pop()
        for k in range(n):
            bit = 1 << k
            if state & bit:
                nxt = state & retained[k]
                if nxt not in seen:
                    seen.add(nxt)
                    stack.append(nxt)

    print(len(seen) % 998244353)

if __name__ == '__main__':
    main()

