import sys

MOD = 998244353

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n = data[0]
    a = data[1:]
    limit = 100000
    spf = list(range(limit + 1))
    for i in range(2, int(limit ** 0.5) + 1):
        if spf[i] == i:
            for j in range(i * i, limit + 1, i):
                if spf[j] == j:
                    spf[j] = i
    phi = list(range(limit + 1))
    for p in range(2, limit + 1):
        if phi[p] == p:
            for j in range(p, limit + 1, p):
                phi[j] -= phi[j] // p
    weighted = [0] * (limit + 1)
    ans = 0
    power = 1
    out = []
    for x in a:
        y = x
        factors = []
        while y > 1:
            p = spf[y]
            e = 0
            while y % p == 0:
                y //= p
                e += 1
            factors.append((p, e))
        divs = [1]
        for p, e in factors:
            old = divs
            divs = []
            mul = 1
            for _ in range(e + 1):
                divs.extend(d * mul for d in old)
                mul *= p
        inc = 0
        for d in divs:
            inc += phi[d] * weighted[d]
        inc %= MOD
        ans = (2 * ans + inc) % MOD
        out.append(str(ans))
        for d in divs:
            v = weighted[d] + power
            if v >= MOD:
                v -= MOD
            weighted[d] = v
        power = power * 2 % MOD
    sys.stdout.write('\n'.join(out))

if __name__ == '__main__':
    main()

