import sys

def main():
    data=list(map(int,sys.stdin.buffer.read().split()))
    if not data: return
    n=data[0]
    a=data[1:1+n]
    mx=max(a, default=1)
    spf=list(range(mx+1))
    for p in range(2,int(mx**0.5)+1):
        if spf[p]==p:
            for q in range(p*p,mx+1,p):
                if spf[q]==q: spf[q]=p
    nim=0
    for v in a:
        g=0
        while v>1:
            v//=spf[v]
            g+=1
        nim ^= g
    print('Anna' if nim else 'Bruno')

if __name__=='__main__': main()

