from typing import List
import heapq

class Solution:
    def maxSubarrays(self, n: int, conflictingPairs: List[List[int]]) -> int:
        events = []
        for i, (a, b) in enumerate(conflictingPairs):
            x, y = sorted((a, b))
            events.append((y, x, i))
        events.sort()

        counts = {}
        ids_by_x = {}
        heap = []  # negative x values, one entry per active distinct x
        gains = [0] * len(conflictingPairs)
        total = 0
        j = 0

        for r in range(1, n + 1):
            while j < len(events) and events[j][0] == r:
                _, x, idx = events[j]
                if counts.get(x, 0) == 0:
                    heapq.heappush(heap, -x)
                counts[x] = counts.get(x, 0) + 1
                ids_by_x.setdefault(x, []).append(idx)
                j += 1

            if not heap:
                top = 0
                total += r
                continue
            top = -heap[0]
            total += r - top
            if counts[top] == 1:
                idx = ids_by_x[top][-1]
                heapq.heappop(heap)
                second = -heap[0] if heap else 0
                heapq.heappush(heap, -top)
                gains[idx] += top - second

        return total + max(gains)

