import sys

def main():
    data=list(map(int,sys.stdin.buffer.read().split()))
    if not data:return
    it=iter(data); n=next(it); m=next(it); q=next(it)
    edges=[]
    for _ in range(m): edges.append((next(it)-1,next(it)-1,next(it)))
    queries=[]; closed=[False]*m
    for _ in range(q):
        t=next(it)
        if t==1:
            e=next(it)-1; queries.append((1,e)); closed[e]=True
        else: queries.append((2,next(it)-1,next(it)-1))
    inf=10**30
    d=[[inf]*n for _ in range(n)]
    for i in range(n):d[i][i]=0
    for k,(u,v,w) in enumerate(edges):
        if not closed[k]:d[u][v]=d[v][u]=w
    for k in range(n):
        dk=d[k]
        for i in range(n):
            dik=d[i][k]
            if dik==inf:continue
            di=d[i]
            for j in range(n):
                z=dik+dk[j]
                if z<di[j]:di[j]=z
    ans=[]
    for qu in reversed(queries):
        if qu[0]==2:
            z=d[qu[1]][qu[2]]; ans.append(str(z if z<inf else -1))
        else:
            u,v,w=edges[qu[1]]
            cu=[d[i][u] for i in range(n)]; cv=[d[i][v] for i in range(n)]
            for i in range(n):
                di=d[i]; iu=cu[i]; iv=cv[i]
                for j in range(i,n):
                    z1=iu+w+cv[j]; z2=iv+w+cu[j]
                    z=di[j]
                    if z1<z:z=z1
                    if z2<z:z=z2
                    if z<di[j]: di[j]=d[j][i]=z
    sys.stdout.write('\n'.join(reversed(ans)))

if __name__=='__main__':main()

