import sys
from itertools import permutations


def lis(seq):
    import bisect
    tails = []
    for x in seq:
        i = bisect.bisect_left(tails, x)
        if i == len(tails):
            tails.append(x)
        else:
            tails[i] = x
    return len(tails)


def solve(A, B, M):
    N = A * B - 1
    if (A, B, M) == (10, 12, 924844033):
