def main():
    data=list(map(int,sys.stdin.buffer.read().split()))
    if not data:
        return
    it=iter(data)
    n=next(it)
    X=next(it)
    procs=[(next(it),next(it),next(it),next(it)) for _ in range(n)]

    def possible(k):
        total=0
        for a,p,b,q in procs:
            f=k//a
            period=b//math.gcd(a,b)
            best=min(((k-a*x+b-1)//b)*q+x*p
                     for r in range(min(period-1,f)+1)
                     for x in (r, r+((f-r)//period)*period))
            x=(k+a-1)//a
            best=min(best,x*p)
            total+=best
            if total>X:
                return False
        return True

    lo,hi=0,X*100+1
    while hi-lo>1:
        mid=(lo+hi)//2
        if possible(mid):
            lo=mid
        else:
            hi=mid
    print(lo)

