class Solution:
    def countKReducibleNumbers(self, s: str, k: int) -> int:
        n = len(s)
        fact = [1] * (n + 1)
        for i in range(1, n + 1):
            fact[i] = fact[i - 1] * i % MOD
        invfact = [1] * (n + 1)
        invfact[n] = pow(fact[n], MOD - 2, MOD)
        for i in range(n, 0, -1):
            invfact[i - 1] = invfact[i] * i % MOD

        def comb(a, b):
            if b < 0 or b > a:
                return 0
            return fact[a] * invfact[b] % MOD * invfact[a - b] % MOD

        valid = [False] * (n + 1)
        for t in range(1, n + 1):
            x = t
            steps = 0
            while x > 1:
                x = x.bit_count()
                steps += 1
            valid[t] = steps <= k - 1

        answer = 0
        prefix_ones = 0
        for i, bit in enumerate(s):
            if bit == '1':
                remaining = n - i - 1
                # Match the prefix, then choose 0 here to become strictly smaller.
                for weight in range(1, n + 1):
                    if valid[weight]:
                        answer += comb(remaining, weight - prefix_ones)
                prefix_ones += 1
        return answer % MOD

