import sys, heapq

N = int(sys.stdin.readline())
g = [sys.stdin.readline().strip() for _ in range(N)]
INF = 10**9
dist = [[INF] * N for _ in range(N)]
heap = []

# Empty paths and one-edge paths are the possible palindrome centers.
for i in range(N):
    dist[i][i] = 0
    heapq.heappush(heap, (0, i, i))
for i in range(N):
    for j, ch in enumerate(g[i]):
        if ch != '-' and dist[i][j] > 1:
            dist[i][j] = 1
            heapq.heappush(heap, (1, i, j))

# incoming[v][c] contains vertices with a c-edge into v;
# outgoing[v][c] contains vertices with a c-edge out of v.
incoming = [[[] for _ in range(26)] for _ in range(N)]
outgoing = [[[] for _ in range(26)] for _ in range(N)]
for u in range(N):
    for v, ch in enumerate(g[u]):
        if ch != '-':
            c = ord(ch) - ord('a')
            outgoing[u][c].append(v)
            incoming[v][c].append(u)

# Extending a palindrome by matching edges on both ends costs two edges.
while heap:
    d, i, j = heapq.heappop(heap)
    if d != dist[i][j]:
        continue
    nd = d + 2
    for c in range(26):
        for a in incoming[i][c]:
            for b in outgoing[j][c]:
                if nd < dist[a][b]:
                    dist[a][b] = nd
                    heapq.heappush(heap, (nd, a, b))

for row in dist:
    print(' '.join(str(-1 if x == INF else x) for x in row))

