data=list(map(int,sys.stdin.buffer.read().split()))
N=data[0]; A=data[1:]
# Search the low binary digits of i.  A crease is mountain precisely when
# the bit following its least significant 1 is zero.
L=62
abits=[[((a>>b)&1) for a in A] for b in range(L+1)]
best=0

def dfs(pos, carries, states, score):
    global best
    unresolved=sum(s<2 for s in states)
    if score+unresolved<=best: return
    if pos==L:
        best=max(best,score)
        return
    for ib in (0,1):
        nc=[]; ns=[]; sc=score
        for j,s in enumerate(states):
            z=ib+abits[pos][j]+carries[j]
            bit=z&1; nc.append(z>>1)
            if s==0:
                if bit: ns.append(1)
                else: ns.append(0)
            elif s==1:
                if bit: ns.append(-1)
                else: ns.append(2); sc+=1
            else: ns.append(s)
        dfs(pos+1,nc,ns,sc)

# Each offset starts with no carry and no 1 bit seen.
dfs(0,[0]*N,[0]*N,0)
print(best)

