import sys

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n, m = data[0], data[1]
    rows = [0] * n
    degree = [0] * n
    pos = 2
    for _ in range(m):
        u = data[pos] - 1
        v = data[pos + 1] - 1
        pos += 2
        rows[u] |= 1 << v
        rows[v] |= 1 << u
        degree[u] += 1
        degree[v] += 1

    # Reduce the adjacency matrix over GF(2) to reduced row-echelon form.
    pivots = []
    r = 0
    for c in range(n):
        pivot_row = next((i for i in range(r, n) if (rows[i] >> c) & 1), None)
        if pivot_row is None:
            continue
        rows[r], rows[pivot_row] = rows[pivot_row], rows[r]
        for i in range(n):
            if i != r and ((rows[i] >> c) & 1):
                rows[i] ^= rows[r]
        pivots.append(c)
        r += 1

    pivot_set = set(pivots)
    free_columns = [c for c in range(n) if c not in pivot_set]
    values = [0] * n

    # Each nullspace basis vector gets its own bit in the output labels.
    # Using bits starting at 2 leaves the labels positive while respecting the limit.
    for j, c in enumerate(free_columns):
        vector = 1 << c
        for row, pivot_col in enumerate(pivots):
            if (rows[row] >> c) & 1:
                vector |= 1 << pivot_col
        for i in range(n):
            if (vector >> i) & 1:
                values[i] |= 1 << (j + 2)

    # Isolated vertices impose no constraint and can be assigned 1 directly.
    for i in range(n):
        if degree[i] == 0:
            values[i] = 1

    if any(value == 0 for value in values):
        print("No")
    else:
        print("Yes")
        print(*values)

if __name__ == "__main__":
    main()

