from typing import List
import math

class Solution:
    def permute(self, n: int, k: int) -> List[int]:
        nums = list(range(1, n + 1))
        fact = [1] * (n + 1)
        for i in range(1, n + 1):
            fact[i] = fact[i - 1] * i

        def ways(remaining, next_parity):
            m = len(remaining)
            odd = sum(x % 2 for x in remaining)
            even = m - odd
            need_odd = (m + 1) // 2 if next_parity == 1 else m // 2
            need_even = m - need_odd
            if odd != need_odd or even != need_even:
                return 0
            return fact[odd] * fact[even]

        ans = []
        prev = None
        while nums:
            chosen = None
            for x in nums:
                if prev is not None and x % 2 == prev:
                    continue
                rem = [y for y in nums if y != x]
                if rem:
                    cnt = ways(rem, 1 - (x % 2))
                else:
                    cnt = 1
                if k > cnt:
                    k -= cnt
                else:
                    chosen = x
                    break
            if chosen is None:
                return []
            ans.append(chosen)
            nums.remove(chosen)
            prev = chosen % 2
        return ans

