class Solution:
    def largestPalindrome(self, n: int, k: int) -> str:
        m = (n + 1) // 2
        coeff = []
        for j in range(m):
            c = pow(10, n - 1 - j, k)
            if j != n - 1 - j:
                c = (c + pow(10, j, k)) % k
            coeff.append(c)

        # Bit r of dp[i] indicates that positions i..m-1 can contribute r modulo k.
        dp = [0] * (m + 1)
        dp[m] = 1  # residue zero
        for i in range(m - 1, -1, -1):
            mask = 0
            c = coeff[i]
            for d in range(10):
                shift = (d * c) % k
                nxt = dp[i + 1]
                for r in range(k):
                    if nxt >> r & 1:
                        mask |= 1 << ((r + shift) % k)
            dp[i] = mask

        left = []
        rem = 0
        for i, c in enumerate(coeff):
            lo = 1 if i == 0 else 0
            for d in range(9, lo - 1, -1):
                need = (-rem - d * c) % k
                if dp[i + 1] >> need & 1:
                    left.append(str(d))
                    rem = (rem + d * c) % k
                    break
        s = ''.join(left)
        return s + (s[:-1][::-1] if n % 2 else s[::-1])

