from typing import List

class Solution:
    def countNonDecreasingSubarrays(self, nums: List[int], k: int) -> int:
        n = len(nums)
        nxt = [n] * n
        stack = []

        # nxt[i] is the next index to the right with a strictly greater value.
        for i in range(n - 1, -1, -1):
            while stack and nums[stack[-1]] <= nums[i]:
                stack.pop()
            nxt[i] = stack[-1] if stack else n
            stack.append(i)

        levels = n.bit_length()
        up = [[n] * n for _ in range(levels)]
        weighted = [[0] * n for _ in range(levels)]
        for i in range(n):
            up[0][i] = nxt[i]
            weighted[0][i] = nums[i] * (nxt[i] - i)

        # Binary lifting over successive prefix-maximum segments.
        for j in range(1, levels):
            for i in range(n):
                middle = up[j - 1][i]
                if middle < n:
                    up[j][i] = up[j - 1][middle]
                    weighted[j][i] = weighted[j - 1][i] + weighted[j - 1][middle]
                else:
                    weighted[j][i] = weighted[j - 1][i]

        prefix_sum = [0]
        for value in nums:
            prefix_sum.append(prefix_sum[-1] + value)

        def increment_cost(left: int, right: int) -> int:
            # Sum of the running maxima minus the original sum.
            current = left
            maximum_sum = 0
            limit = right + 1
            for j in range(levels - 1, -1, -1):
                if current < n and up[j][current] <= limit:
                    maximum_sum += weighted[j][current]
                    current = up[j][current]
            if current <= right:
                maximum_sum += nums[current] * (right - current + 1)
            return maximum_sum - (prefix_sum[right + 1] - prefix_sum[left])

        answer = 0
        for right in range(n):
            # Cost decreases as left moves right, so feasible starts form a suffix.
            low, high = 0, right
            while low < high:
                middle = (low + high) // 2
                if increment_cost(middle, right) <= k:
                    high = middle
                else:
                    low = middle + 1
            answer += right - low + 1

        return answer

