class Solution:
    def makeStringGood(self, s: str) -> int:
        from collections import Counter
        cnt = [0] * 26
        for ch in s:
            cnt[ord(ch) - 97] += 1
        n = len(s)
        ans = n
        # Enumerate the common positive frequency. For each letter, the state is
        # the number of characters carried into it from the preceding letter.
        for k in range(1, max(cnt) + 1):
            # dp[x]: minimum cost before processing the next letter, with x
            # characters arriving from the previous letter.
            dp = [0] + [n + 1] * n
            for c in cnt:
                ndp = [n + 1] * (n + 1)
                # Final count at this letter is either zero or k. If y chars
                # are sent onward, insertion/deletion accounts for the balance.
                for x, base in enumerate(dp):
                    if base > n:
                        continue
                    for y in range(n + 1):
                        cost = base + y
                        v = cost + abs(c + x - y)
                        if v < ndp[y]:
                            ndp[y] = v
                        v = cost + abs(c + x - y - k)
                        if v < ndp[y]:
                            ndp[y] = v
                dp = ndp
            ans = min(ans, min(dp))
        return ans

