class Solution:
    def maximizeSumOfWeights(self, edges: List[List[int]], k: int) -> int:
        n = len(edges) + 1
        adj = [[] for _ in range(n)]
        for u, v, w in edges:
            adj[u].append((v, w))
            adj[v].append((u, w))

        parent = [-1] * n
        parent[0] = 0
        order = [0]
        for u in order:
            for v, _ in adj[u]:
                if v != parent[u]:
                    parent[v] = u
                    order.append(v)

        without_parent = [0] * n
        with_parent = [0] * n
        for u in reversed(order):
            base = 0
            gains = []
            for v, w in adj[u]:
                if parent[v] == u:
                    base += without_parent[v]
                    gains.append(w + with_parent[v] - without_parent[v])
            gains.sort(reverse=True)
            positive_gains = [gain for gain in gains if gain > 0]
            without_parent[u] = base + sum(positive_gains[:k])
            with_parent[u] = base + sum(positive_gains[:max(0, k - 1)])

        return without_parent[0]

