from bisect import bisect_left

class Solution:
    def shortestMatchingSubstring(self, s: str, p: str) -> int:
        n = len(s)
        a, b, c = p.split('*')

        def occurrences(t):
            if not t:
                return list(range(n + 1))
            m = len(t)
            pi = [0] * m
            j = 0
            for i in range(1, m):
                while j and t[i] != t[j]:
                    j = pi[j - 1]
                if t[i] == t[j]:
                    j += 1
                pi[i] = j
            out = []
            j = 0
            for i, ch in enumerate(s):
                while j and ch != t[j]:
                    j = pi[j - 1]
                if ch == t[j]:
                    j += 1
                if j == m:
                    out.append(i - m + 1)
                    j = pi[j - 1]
            return out

        aa, bb, cc = occurrences(a), occurrences(b), occurrences(c)
        ans = n + 1
        for x in aa:
            ib = bisect_left(bb, x + len(a))
            if ib == len(bb):
                continue
            y = bb[ib]
            ic = bisect_left(cc, y + len(b))
            if ic == len(cc):
                continue
            z = cc[ic]
            ans = min(ans, z + len(c) - x)
        return -1 if ans == n + 1 else ans

