def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n, m = data[0], data[1]
    g = [[] for _ in range(n)]
    k = 2
    for _ in range(m):
        x, y, z = data[k]-1, data[k+1]-1, data[k+2]
        k += 3
        g[x].append((y,z))
        g[y].append((x,z))
    p = [None]*n
    ans = [0]*n
    for start in range(n):
        if p[start] is not None:
            continue
        p[start] = 0
        stack = [start]
        comp = []
        while stack:
            v = stack.pop()
            comp.append(v)
            for u,z in g[v]:
                w = p[v] ^ z
                if p[u] is None:
                    p[u] = w
                    stack.append(u)
                elif p[u] != w:
                    print(-1)
                    return
        t = 0
        for bit in range(31):
            ones = sum((p[v] >> bit) & 1 for v in comp)
            zeros = len(comp) - ones
            if zeros < ones:
                t |= 1 << bit
        for v in comp:
            ans[v] = p[v] ^ t
    print(*ans)

