    out = []
    for _ in range(t):
        n = int(data[p]); a = data[p + 1].decode(); b = data[p + 2].decode(); p += 3
        src = [i for i, c in enumerate(a) if c == '1']
        dst = [i for i, c in enumerate(b) if c == '1']
        if len(src) < len(dst):
            out.append('-1')
            continue
        def possible(k):
            prev = [True] * len(src)
            for q, y in enumerate(dst):
                cur = [False] * len(src)
                gap = 0 if q == 0 else y - dst[q - 1]
                for j, x in enumerate(src):
                    if abs(x - y) > k:
                        continue
                    if q == 0:
                        cur[j] = True
                    else:
                        for h in range(j):
                            if prev[h] and x - src[h] >= gap:
