                                break
                prev = cur
            return any(prev)
        lo, hi = 0, n
        while lo < hi:
            mid = (lo + hi) // 2
            if possible(mid): hi = mid
            else: lo = mid + 1
        out.append(str(lo))
    print('\n'.join(out))

