from typing import List

class Solution:
    def findAnswer(self, parent: List[int], s: str) -> List[bool]:
        n = len(parent)
        children = [[] for _ in range(n)]
        for v in range(1, n):
            children[parent[v]].append(v)

        # Produce the recursive DFS postorder without using Python recursion.
        postorder = []
        stack = [(0, 0)]
        while stack:
            x, state = stack.pop()
            if state:
                postorder.append(x)
            else:
                stack.append((x, 1))
                for y in reversed(children[x]):
                    stack.append((y, 0))

        position = [0] * n
        subtree_size = [1] * n
        chars = []
        for i, x in enumerate(postorder):
            position[x] = i
            chars.append(s[x])
            if parent[x] != -1:
                subtree_size[parent[x]] += subtree_size[x]
        text = ''.join(chars)

        # Manacher radii: odd[i] includes the center; even[i] is centered
        # between i-1 and i.
        odd = [0] * n
        left, right = 0, -1
        for i in range(n):
            k = 1 if i > right else min(odd[left + right - i], right - i + 1)
            while i - k >= 0 and i + k < n and text[i - k] == text[i + k]:
                k += 1
            odd[i] = k
            if i + k - 1 > right:
                left, right = i - k + 1, i + k - 1

        even = [0] * n
        left, right = 0, -1
        for i in range(n):
            k = 0 if i > right else min(even[left + right - i + 1], right - i + 1)
            while i - k - 1 >= 0 and i + k < n and text[i - k - 1] == text[i + k]:
                k += 1
            even[i] = k
            if i + k - 1 > right:
                left, right = i - k, i + k - 1

        answer = [False] * n
        for x in range(n):
            end = position[x]
            length = subtree_size[x]
            start = end - length + 1
            if length & 1:
                answer[x] = odd[(start + end) // 2] >= length // 2 + 1
            else:
                answer[x] = even[(start + end + 1) // 2] >= length // 2
        return answer

