class Solution:
    def maxSubarraySum(self, nums: List[int], k: int) -> int:
        # Prefix indices with equal remainder modulo k define lengths divisible by k.
        min_prefix = [None] * k
        min_prefix[0] = 0
        prefix = 0
        best = None

        for i, value in enumerate(nums, 1):
            prefix += value
            remainder = i % k
            previous = min_prefix[remainder]
            if previous is not None:
                candidate = prefix - previous
                if best is None or candidate > best:
                    best = candidate
            if previous is None or prefix < previous:
