from collections import Counter
class Solution:
    def getLargestOutlier(self, nums: List[int]) -> int:
        total = sum(nums)
        freq = Counter(nums)
        for x in sorted(freq, reverse=True):
            rem = total - x
            if rem % 2 == 0:
                y = rem // 2
                if freq[y] >= (2 if y == x else 1):
                    return x
        return 0

