import heapq

class Solution:
    def minOperations(self, n: int, m: int) -> int:
        limit = 10 ** len(str(n)) - 1
        prime = bytearray(b'\x01') * (limit + 1)
        prime[0] = 0
        if limit >= 1:
            prime[1] = 0
        for p in range(2, int(limit ** 0.5) + 1):
            if prime[p]:
                prime[p * p:limit + 1:p] = b'\x00' * (((limit - p * p) // p) + 1)

        if prime[n] or prime[m]:
            return -1

        inf = 10**30
        dist = {n: n}  # The starting value is included in the total cost.
        queue = [(n, n)]

        while queue:
            cost, value = heapq.heappop(queue)
            if cost != dist.get(value):
                continue
            if value == m:
                return cost

            place = 1
            # Zero itself has one digit, which can be increased to 1.
            while place <= max(value, 1):
                digit = (value // place) % 10
                for change in (-1, 1):
                    if (change == -1 and digit == 0) or (change == 1 and digit == 9):
                        continue
                    nxt = value + change * place
                    if not prime[nxt]:
                        new_cost = cost + nxt
                        if new_cost < dist.get(nxt, inf):
                            dist[nxt] = new_cost
                            heapq.heappush(queue, (new_cost, nxt))
                place *= 10

        return -1

