from typing import List

class Solution:
    def beautifulSplits(self, nums: List[int]) -> int:
        n = len(nums)
        z0 = [0] * n
        l = r = 0
        for k in range(1, n):
            if k < r:
                z0[k] = min(r - k, z0[k - l])
            while k + z0[k] < n and nums[z0[k]] == nums[k + z0[k]]:
                z0[k] += 1
            if k + z0[k] > r:
                l, r = k, k + z0[k]

        ans = 0
        for i in range(1, n - 1):
            m = n - i
            z = [0] * m
            l = r = 0
            for k in range(1, m):
                if k < r:
                    z[k] = min(r - k, z[k - l])
                while k + z[k] < m and nums[i + z[k]] == nums[i + k + z[k]]:
                    z[k] += 1
                if k + z[k] > r:
                    l, r = k, k + z[k]

            first_ok = z0[i] >= i
            for d in range(1, m):
                if m - d < 1:
                    break
                if (first_ok and d >= i) or z[d] >= d:
                    ans += 1
        return ans

