from typing import List

class Solution:
    def maxRemovals(self, source: str, pattern: str, targetIndices: List[int]) -> int:
        n, m = len(source), len(pattern)
        marked = [False] * n
        for i in targetIndices:
            marked[i] = True

        neg = -10**9
        dp = [neg] * (m + 1)
        dp[0] = 0

        for i, c in enumerate(source):
            # Descending order keeps dp[j - 1] from the previous source index.
            for j in range(m, -1, -1):
                best = dp[j]
                if marked[i] and best > neg:
                    best += 1  # remove this target character
                if j > 0 and c == pattern[j - 1]:
                    best = max(best, dp[j - 1])  # retain it as a match
                dp[j] = best

        return dp[m]

