from typing import List

class Solution:
    def minMaxWeight(self, n: int, edges: List[List[int]], threshold: int) -> int:
        # Traverse reversed edges from node 0; this visits exactly nodes that
        # can reach 0 in the original graph.
        rev = [[] for _ in range(n)]
        for a, b, w in edges:
            rev[b].append((a, w))

        weights = sorted({w for _, _, w in edges})

        def all_reach_zero(limit: int) -> bool:
            seen = bytearray(n)
            seen[0] = 1
            stack = [0]
            count = 1
            while stack:
                v = stack.pop()
                for u, w in rev[v]:
                    if w <= limit and not seen[u]:
                        seen[u] = 1
                        count += 1
                        stack.append(u)
            return count == n

        if not all_reach_zero(weights[-1]):
            return -1

        lo, hi = 0, len(weights) - 1
        while lo < hi:
            mid = (lo + hi) // 2
            if all_reach_zero(weights[mid]):
                hi = mid
            else:
                lo = mid + 1
        return weights[lo]

