class Solution:
    def minCost(self, n: int, cost: List[List[int]]) -> int:
        pairs = [(a, b) for a in range(3) for b in range(3) if a != b]
        # dp[p] is the least cost for the pairs processed so far,
        # ending with ordered colors p = (left, right).
        dp = [cost[0][a] + cost[n - 1][b] for a, b in pairs]
        for i in range(1, n // 2):
            ndp = [10**30] * 6
            for j, (a, b) in enumerate(pairs):
                add = cost[i][a] + cost[n - 1 - i][b]
                for k, (x, y) in enumerate(pairs):
                    if a != x and b != y:
                        ndp[j] = min(ndp[j], dp[k] + add)
            dp = ndp
        return min(dp)

