class Solution:
    def maxActiveSectionsAfterTrade(self, s: str) -> int:
        ones = s.count('1')
        runs = []
        i = 0
        while i < len(s):
            j = i + 1
            while j < len(s) and s[j] == s[i]:
                j += 1
            runs.append((s[i], j - i))
            i = j

        # Any internal zero-run can be converted independently after the
        # selected one-run is removed. Its gain is its length minus the
        # number of ones that were removed.
        zero_max = max((length for ch, length in runs if ch == '0'), default=0)
        best_gain = 0  # choosing no trade

        for k, (ch, length) in enumerate(runs):
            if ch == '1' and 0 < k < len(runs) - 1:
                # Removing this one-run joins its two neighboring zero-runs;
                # converting that joined block gains both zero-run lengths.
                gain = max(
                    runs[k - 1][1] + runs[k + 1][1],
                    zero_max - length,
                )
                best_gain = max(best_gain, gain)

        return ones + best_gain

