class Solution:
    def maxRectangleArea(self, points: List[List[int]]) -> int:
        p = {tuple(q) for q in points}
        xs = sorted({x for x, y in p})
        ys = sorted({y for x, y in p})
        ans = -1
        for i, x1 in enumerate(xs):
            for x2 in xs[i+1:]:
                for j, y1 in enumerate(ys):
                    for y2 in ys[j+1:]:
                        corners = ((x1,y1),(x1,y2),(x2,y1),(x2,y2))
                        if not all(c in p for c in corners):
                            continue
                        if any(x1 <= x <= x2 and y1 <= y <= y2 and (x,y) not in corners for x,y in p):
                            continue
                        ans = max(ans, (x2-x1)*(y2-y1))
        return ans

