from typing import List

class Solution:
    def countArrays(self, original: List[int], bounds: List[List[int]]) -> int:
        # Every valid copy differs from original by the same constant offset.
        low = max(u - x for x, (u, v) in zip(original, bounds))
        high = min(v - x for x, (u, v) in zip(original, bounds))
        return max(0, high - low + 1)
